//! Emoji data (generated by `build.rs`), search and lookup.
use std::{
    collections::HashMap,
    sync::{
        OnceLock,
        atomic::{AtomicUsize, Ordering},
    },
};

use crate::fold::fold;

include!(concat!(env!("OUT_DIR"), "/emoji_data.rs"));

/// Display order: (id, icon emoji); titles are `Tr.category(i)` in the UI. Index 0 is the recents pseudo-category.
pub const CATEGORIES: [(&str, &str); 9] = [
    ("recent", "🕙"),
    ("smileys-people", "🙂"),
    ("animals-nature", "🐯"),
    ("food-drink", "🍔"),
    ("activities", "⚽"),
    ("travel-places", "✈️"),
    ("objects", "💡"),
    ("symbols", "⁉️"),
    ("flags", "🇺🇳"),
];

/// 0 = English, otherwise 1 + index into `L10N`.
static LANG: AtomicUsize = AtomicUsize::new(0);

/// Codes of the translated languages (also the `translations/` folder names), in `L10N` order.
pub fn language_codes() -> impl Iterator<Item = &'static str> {
    L10N.iter().map(|l| l.0)
}

/// Canonical language for a user preference or a POSIX locale ("pt_BR.UTF-8", "fr", "en_US"); "en" if unsupported.
pub fn resolve_language(locale: &str) -> &'static str {
    let locale = locale.split(['.', '@']).next().unwrap_or("");
    let base = |l: &str| l.split(['_', '-']).next().unwrap_or("").to_string();
    language_codes()
        .find(|c| *c == locale)
        .or_else(|| language_codes().find(|c| base(c) == base(locale)))
        .unwrap_or("en")
}

/// Select the language of names and search (a code from `resolve_language`).
pub fn set_language(code: &str) {
    let index = L10N.iter().position(|l| l.0 == code).map_or(0, |i| i + 1);
    LANG.store(index, Ordering::Relaxed);
}

fn localized(index: usize) -> Option<&'static (&'static str, &'static str)> {
    let entry = &L10N[LANG.load(Ordering::Relaxed).checked_sub(1)?].1[index];
    (!entry.0.is_empty()).then_some(entry)
}

/// Display name in the selected language (English when it has no translation).
pub fn name(index: usize) -> &'static str {
    localized(index).map_or(EMOJIS[index].name, |l| l.0)
}

/// Emoji indices of a category (index into `CATEGORIES`, never 0).
pub fn in_category(category: usize) -> &'static [u16] {
    BY_CATEGORY[category - 1]
}

/// Case- and accent-insensitive substring match over the name and keywords, in the selected language and English.
pub fn search(query: &str) -> Vec<usize> {
    if query.contains('\u{1}') {
        return Vec::new();
    }
    let query = fold(query);
    EMOJIS
        .iter()
        .enumerate()
        .filter(|(i, e)| e.terms.contains(&query) || localized(*i).is_some_and(|l| l.1.contains(&query)))
        .map(|(i, _)| i)
        .collect()
}

pub fn is_tone_modifier(c: char) -> bool {
    ('\u{1F3FB}'..='\u{1F3FF}').contains(&c)
}

pub fn strip_tone(s: &str) -> String {
    s.chars().filter(|c| !is_tone_modifier(*c)).collect()
}

fn normalize(s: &str) -> String {
    s.chars()
        .filter(|c| !is_tone_modifier(*c) && *c != '\u{FE0F}')
        .collect()
}

/// Find an emoji by character, ignoring skin tone and the emoji-presentation selector.
pub fn find_by_char(ch: &str) -> Option<usize> {
    static INDEX: OnceLock<HashMap<String, usize>> = OnceLock::new();
    let index = INDEX.get_or_init(|| {
        let mut map = HashMap::with_capacity(EMOJIS.len());
        for (i, e) in EMOJIS.iter().enumerate() {
            map.entry(normalize(e.ch)).or_insert(i);
        }
        map
    });
    index.get(&normalize(ch)).copied()
}

/// The character to show/copy for the chosen skin tone (0 = default).
pub fn char_for(index: usize, tone: usize) -> &'static str {
    let e = &EMOJIS[index];
    if tone > 0 && e.has_tones && !e.tones[tone - 1].is_empty() {
        e.tones[tone - 1]
    } else {
        e.ch
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn search_finds_by_name_and_keyword() {
        let hits = search("grinning");
        assert!(hits.iter().any(|&i| EMOJIS[i].ch == "😀"));
        assert!(!search("brazil").is_empty());
        assert!(search("zzzzqqqq").is_empty());
    }

    #[test]
    fn search_does_not_cross_term_boundaries() {
        assert!(search("face\u{1}").is_empty());
    }

    #[test]
    fn find_ignores_tone_and_variation_selector() {
        assert!(find_by_char("❤").is_some());
        assert_eq!(find_by_char("👍🏽"), find_by_char("👍"));
    }

    #[test]
    fn tones_are_linked() {
        let thumbs = find_by_char("👍").unwrap();
        // The base glyph carries the emoji-presentation selector (U+FE0F), as in the CSV.
        assert_eq!(strip_tone(char_for(thumbs, 0)).trim_end_matches('\u{FE0F}'), "👍");
        assert_eq!(char_for(thumbs, 3), "👍🏽");
    }

    #[test]
    fn localized_names_and_accent_insensitive_search() {
        set_language("pt_BR");
        assert!(search("CORAÇÃO").iter().any(|&i| EMOJIS[i].ch.starts_with('❤')));
        assert!(search("coracao").iter().any(|&i| EMOJIS[i].ch.starts_with('❤')));
        assert!(!search("grinning").is_empty(), "English keeps working");
        let smile = find_by_char("😀").unwrap();
        assert_ne!(name(smile), EMOJIS[smile].name);
        set_language("ja");
        assert!(!search("笑").is_empty());
        set_language("en");
        assert_eq!(name(smile), EMOJIS[smile].name);
    }

    #[test]
    fn language_resolution() {
        assert_eq!(resolve_language("pt_BR.UTF-8"), "pt_BR");
        assert_eq!(resolve_language("pt_PT"), "pt_BR");
        assert_eq!(resolve_language("zh_TW"), "zh_CN");
        assert_eq!(resolve_language("fr"), "fr");
        assert_eq!(resolve_language("en_US.UTF-8"), "en");
        assert_eq!(resolve_language("C"), "en");
    }

    #[test]
    fn every_category_has_emoji() {
        for (c, category) in CATEGORIES.iter().enumerate().skip(1) {
            assert!(!in_category(c).is_empty(), "{}", category.0);
        }
    }
}
